import http from "k6/http";
import { check, sleep } from "k6";

export const options = {
  stages: [
    { duration: "2m", target: 100 },  // 2 分钟爬升到 100 个虚拟用户
    { duration: "5m", target: 100 },  // 保持 5 分钟
    { duration: "1m", target: 0 },    // 回落
  ],
  thresholds: {
    http_req_duration: ["p(95)<500"], // 95% 请求低于 500ms
    http_req_failed: ["rate<0.01"],   // 错误率低于 1%
  },
};

export default function () {
  const res = http.get("https://staging.example.com/api/products");
  check(res, { "status is 200": (r) => r.status === 200 });
  sleep(1); // 模拟用户思考时间
}

# main.tf（HCL 语法）
terraform {
  backend "s3" {                      # 远程状态，团队共享
    bucket = "acme-tf-state"
    key    = "prod/storage.tfstate"
    region = "ap-southeast-1"
  }
}

provider "aws" { region = "ap-southeast-1" }

resource "aws_s3_bucket" "logs" {
  bucket = "acme-prod-logs"
  tags   = { owner = "platform", env = "prod" }
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id
  versioning_configuration { status = "Enabled" }
}

# 流程：terraform init → terraform plan（评审）→ terraform apply
